  box-shadow: 0 8px 22px rgba(0,0,0,.45); animation: toast-in .2s ease;
}
.toast.gold { border-color: var(--gold); color: var(--gold); }
.toast.red { border-color: var(--red); }
@keyframes toast-in { from { transform: translateY(12px); opacity: 0; } }

/* ---------- play page (game client) ---------- */
#game-root { position: fixed; inset: 0; background: #000; z-index: 200; }
#game-root canvas.game-canvas { width: 100%; height: 100%; display: block; }
.hud { position: absolute; pointer-events: none; }
.hud * { pointer-events: auto; }
#hud-top { top: 10px; left: 12px; right: 12px; display: flex; align-items: flex-start; pointer-events: none; }
#hud-gamename { background: rgba(10,25,35,.75); border-radius: 8px; padding: 7px 14px; font-weight: 700; }
#hud-leave { margin-left: 10px; }
#hud-lb {
  margin-left: auto; background: rgba(10,25,35,.75); border-radius: 8px;
  min-width: 190px; padding: 8px 0; font-size: 13px;
}
#hud-lb .lb-title { padding: 0 12px 6px; color: var(--dim); font-weight: 700; border-bottom: 1px solid var(--line); display:flex; }
#hud-lb .lb-row { padding: 4px 12px; display: flex; }
#hud-lb .lb-row.it { color: #ff6b6b; font-weight: 700; }
#hud-lb .lb-row .v { margin-left: auto; }
#hud-chat { left: 12px; bottom: 12px; width: 330px; }
#chat-log { max-height: 180px; overflow-y: auto; font-size: 13px; margin-bottom: 6px; display: flex; flex-direction: column; gap: 2px; }
#chat-log div { background: rgba(10,25,35,.7); border-radius: 6px; padding: 4px 9px; width: fit-content; max-width: 100%; word-wrap: break-word; }
#chat-log .sys { color: var(--dim); font-style: italic; }
#chat-log b { color: var(--accent); }
#chat-input { background: rgba(10,25,35,.85); border: 1px solid var(--line); }
#hud-center { top: 38%; left: 0; right: 0; text-align: center; font-size: 30px; font-weight: 800; text-shadow: 0 2px 12px #000; }
#hud-controls-hint { right: 12px; bottom: 12px; color: #9ab; font-size: 12px; background: rgba(10,25,35,.6); padding: 6px 10px; border-radius: 8px; }

/* ---------- studio ---------- */
#studio-root { position: fixed; inset: 0; background: #000; z-index: 200; display: flex; flex-direction: column; }
#studio-topbar { height: 46px; background: var(--bg2); border-bottom: 1px solid var(--line); display: flex; align-items: center; gap: 8px; padding: 0 10px; z-index: 5; }
#studio-topbar .title { font-weight: 800; margin-right: 8px; }
#studio-main { flex: 1; position: relative; display: flex; min-height: 0; }
#studio-canvas-wrap { flex: 1; position: relative; min-width: 0; }
#studio-canvas-wrap canvas { width: 100%; height: 100%; display: block; }
#studio-side { width: 280px; background: var(--bg2); border-left: 1px solid var(--line); overflow-y: auto; padding: 12px; font-size: 13px; }
#studio-side h3 { font-size: 13px; text-transform: uppercase; letter-spacing: 1px; color: var(--dim); margin: 14px 0 8px; }
#studio-side h3:first-child { margin-top: 0; }
.tool-btn {
  background: var(--panel); color: var(--text); border: 1px solid var(--line);
  border-radius: 7px; padding: 6px 12px; cursor: pointer; font-weight: 600; font-size: 13px;
}
.tool-btn.active { background: var(--accent); color: #062536; border-color: var(--accent); }
.part-palette { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.part-palette .tool-btn { padding: 8px 4px; text-align: center; font-size: 12px; }
.editor-chip { display: inline-flex; align-items: center; gap: 6px; background: var(--panel); padding: 3px 10px 3px 6px; border-radius: 20px; font-size: 12px; font-weight: 600; }
.editor-chip .dot { width: 10px; height: 10px; border-radius: 50%; }
.prop-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px; }
.prop-grid input { padding: 6px 8px; font-size: 13px; }
#studio-chat-log { max-height: 120px; overflow-y: auto; font-size: 12px; display: flex; flex-direction: column; gap: 2px; margin-bottom: 6px; }
#studio-chat-log b { color: var(--accent); }

.empty-note { color: var(--dim); text-align: center; padding: 40px 0; }
table.cfg { width: 100%; border-collapse: collapse; font-size: 14px; }
table.cfg td { padding: 6px 8px; border-bottom: 1px solid var(--line); }
table.cfg td:first-child { color: var(--dim); }
